"""
ClickUp task generator agent.

This module defines the ClickUpTaskGeneratorAgent, responsible for generating
ClickUp tasks from a backlog using an LLM. It transforms unstructured sprint
backlog content into structured domain tasks compatible with ClickUp workflow.
"""

import logging
import json
from typing import List, Dict

from openai import APIStatusError, APIConnectionError
from openai.types.chat import ChatCompletionSystemMessageParam, ChatCompletionUserMessageParam

from backend.src.domain.entities.generated_tasks.generated_task_from_backlog import GeneratedTaskFromBacklog, \
    GeneratedTaskListFromBacklog
from backend.src.domain.entities.sprint.sprint import Sprint
from backend.src.domain.exceptions.llm.llm_api_exception import LLMApiException
from backend.src.domain.exceptions.llm.llm_network_exception import LLMNetworkException
from backend.src.domain.exceptions.llm.llm_parsing_exception import LLMParsingException
from backend.src.domain.ports.services.task_generation_from_backlog.i_task_generator_from_backlog import ITaskGeneratorFromBacklog
from backend.src.infrastructure.external.shared.agents.base_agent import BaseAgent


logger = logging.getLogger(__name__)


class ClickUpTaskGeneratorFromBacklogAgent(BaseAgent, ITaskGeneratorFromBacklog):
    """
    LLM-based implementation of ITaskGenerator.

    This agent is responsible for:
    - Generating ClickUp tasks from a backlog
    - Mapping unstructured text into structured task entities
    - Aligning tasks with available folders, statuses, and priorities
    """

    def generate_tasks(
        self,
        sprint_backlog: Sprint,
        locations_statuses: Dict[str, Dict[str, List[str]]]
    ) -> List[GeneratedTaskFromBacklog]:
        """
        Generate ClickUp tasks from a backlog using an LLM.

        This method:
        - Sends the backlog and workspace structure to the LLM
        - Uses prompt templates to guide structured task generation
        - Parses the LLM response into domain task objects

        Args:
            sprint_backlog: sprint backlog content.
            locations_statuses: Mapping of locations to available statuses and priorities.

        Returns:
            List[GeneratedTask]: List of structured tasks generated by the LLM.

        Raises:
            LLMNetworkException: If a network error occurs while contacting the LLM.
            LLMApiException: If the LLM API returns an error response.
            LLMParsingException: If the LLM response cannot be parsed correctly.
        """
        logger.info("Starting task generation process from backlog.")

        # Convert the dictionary to JSON text to provide to the LLM
        if locations_statuses:
            locations_text = json.dumps(locations_statuses, ensure_ascii=False, indent=2)
        else:
            locations_text = "No locations available."

        messages = self.prompt_loader.get_messages(
            folder_name="task_generation_backlog",
            name="clickup_task_generator_agent",
            variables={
                "backlog": ClickUpTaskGeneratorFromBacklogAgent._format_sprints(sprint_backlog),
                "locations_text" : locations_text
            }
        )

        messages = [
            ChatCompletionSystemMessageParam(role="system", content=messages["system"]),
            ChatCompletionUserMessageParam(role="user", content=messages["user"])
        ]

        try:
            response = self.client.chat.completions.parse(
                model=self.model,
                messages=messages,
                temperature=0,
                response_format=GeneratedTaskListFromBacklog,
            )

        except APIConnectionError as e:
            logger.exception("Network error contacting LLM in ClickUpTaskGeneratorAgent: reason=%s.", str(e))
            raise LLMNetworkException() from e

        except APIStatusError as e:
            logger.exception("LLM API error in ClickUpTaskGeneratorAgent: status=%d.", e.status_code)
            raise LLMApiException() from e

        except Exception as e:
            logger.exception("Click up tasks generating from backlog failed: reason=%s.", str(e))
            raise LLMParsingException() from e

        parsed: GeneratedTaskListFromBacklog = response.choices[0].message.parsed
        if not parsed or not parsed.tasks:
            logger.warning("No tasks extracted from backlog.")
            return []

        logger.info(
            "Task generating from backlog completed successfully: %d task(s) generated.",
            len(parsed.tasks)
        )

        return parsed.tasks

    @staticmethod
    def _format_sprints(backlog: Sprint) -> str:
        lines = [
            f"Sprint: {backlog.name}",
            f"Goal: {backlog.goal}",
            f"Total Estimated Hours: {backlog.total_estimated_hours}h",
            ""
        ]

        for us_sprint in backlog.user_stories:
            us = us_sprint.user_story
            lines.append(f"  User Story: {us.title}")

            if us.description:
                lines.append(f"  Description: {us.description}")
            lines.append("")

            for task_estimate in us_sprint.tasks:
                task = task_estimate.task
                lines.append(f"    - Task: {task.title}")
                lines.append(f"      Description: {task.description}")
                lines.append(f"      Estimated Hours: {task_estimate.estimated_hours}h")
                lines.append("")

        return "\n".join(lines)